-- Occasions: golf plus casual/weekend for all thirty-nine. None is a work shirt - Max is in a bank.
INSERT INTO item_occasions (item_id, occasion_code)
SELECT id, o FROM items CROSS JOIN (VALUES ('golf'),('casual'),('weekend')) v(o)
WHERE id BETWEEN 'tops_61' AND 'tops_99_zzz'
ON CONFLICT DO NOTHING;

-- Colour provenance. Same method as migration 048, with the white-point fix described in the
-- header: candidates for the white reference now EXCLUDE the garment's own box, so a pale
-- garment can no longer be its own neutral.
INSERT INTO item_field_sources (item_id, field_name, source, note)
SELECT id, 'hex', 'derived',
       'MEASURED against the white table in the same frame, 2026-08-31. White point = 97th percentile per channel of the low-saturation pixels in a frame-interior annulus with the garment box removed; garment = median of the garment box with the darkest quartile and brightest decile discarded. The exclusion of the garment box is new in this batch and was necessary: on the first pass the khaki FootJoy and the peach Under Armour measured as neutral greys because the garment was acting as its own white reference.'
FROM items WHERE id BETWEEN 'tops_61' AND 'tops_99_zzz'
  AND id NOT IN ('tops_68_peter-millar-white-rsgc-polo-m','tops_69_glenmuir-cream-mercerised-polo',
                 'tops_78_woollahra-white-micro-floral-polo','tops_93_stone-rsgc-polo',
                 'tops_94_gfore-camiral-camo-polo','tops_95_abacus-bonville-white-polo',
                 'tops_96_adidas-ocean-dunes-white-polo','tops_97_calvin-klein-barnbougle-dunes-polo',
                 'tops_98_bcln-white-orange-polo','tops_99_bermuda-sands-hope-island-polo')
ON CONFLICT DO NOTHING;

-- The ten near-whites. Same failure as tops_52 and tops_53: on a white or near-white garment the
-- central region is mostly shadow and the method faithfully measures the shadow, returning
-- values between #C0C2BF and #DADCDB. Set near-white by judgement.
INSERT INTO item_field_sources (item_id, field_name, source, note)
SELECT id, 'hex', 'derived',
       'White or near-white garment. Measurement returned a mid grey because it was reading shadow across the cloth, not colour. Hex set near-white by judgement, as on tops_52 and tops_53.'
FROM items WHERE id IN ('tops_68_peter-millar-white-rsgc-polo-m','tops_69_glenmuir-cream-mercerised-polo',
                        'tops_78_woollahra-white-micro-floral-polo','tops_93_stone-rsgc-polo',
                        'tops_94_gfore-camiral-camo-polo','tops_95_abacus-bonville-white-polo',
                        'tops_96_adidas-ocean-dunes-white-polo','tops_97_calvin-klein-barnbougle-dunes-polo',
                        'tops_98_bcln-white-orange-polo','tops_99_bermuda-sands-hope-island-polo')
ON CONFLICT DO NOTHING;

-- Deliberate non-identifications. These follow tops_58: the mark exists, it was zoomed, it could
-- not be read, and nothing was guessed. Marked manual so a re-import cannot quietly fill them in.
INSERT INTO item_field_sources (item_id, field_name, source, note) VALUES
('tops_61_rose-unbranded-polo','notes','manual','Brand UNKNOWN and deliberately blank. The only neck tag in frame is a size tag (M, 100% polyester, made in China); no brand mark appears anywhere on the garment in either photograph. Do not guess a brand into this row.'),
('tops_70_footjoy-khaki-polo','formality_note','manual','A dark navy crest sits on the left chest and was not legible at full resolution. It has NOT been named as Royal Sydney or anything else. Re-shoot the chest if the club matters.'),
('tops_71_nike-charcoal-piped-polo','notes','manual','A small pale script embroidery on the left chest was zoomed and could not be read. No club asserted.'),
('tops_72_barnbougle-lost-farm-charcoal-polo','notes','manual','Brand UNKNOWN. The chest reads Barnbougle LOST FARM but no maker''s label appears in either photograph. Do not guess a brand into this row.'),
('tops_73_royal-melbourne-navy-argyle-polo','notes','manual','Brand UNKNOWN. Royal Melbourne crest read cleanly; no maker''s label in frame. The second photograph is a macro of a hem pocket whose debossed mark could not be read.'),
('tops_78_woollahra-white-micro-floral-polo','notes','manual','ONE PHOTOGRAPH ONLY - no neck label was shot, so brand and size are both unknown. Shoot the label next time this comes out of the drawer.'),
('tops_80_red-unbranded-polo','notes','manual','Brand UNKNOWN. Neck tag reads M/M, MADE IN CHINA and nothing more; the small dark chest logo was zoomed and is not legible. Do not guess.'),
('tops_86_grey-peru-unbranded-polo','notes','manual','Brand UNKNOWN. The black brand tag at the neck is photographed but completely illegible; the size tag beside it reads S, MADE IN PERU. Do not guess.'),
('tops_92_barbaroux-grey-polo','notes','manual','Brand UNKNOWN. Golf Club Barbaroux crest read cleanly; the debossed neck mark could not be read.'),
('tops_93_stone-rsgc-polo','notes','manual','Brand UNKNOWN and size unread - no brand or size tag appears in either photograph.'),
('tops_64_peter-millar-red-interclub-polo-m','fit','manual','Size M read at full resolution off the neck label visible in this garment''s own flat-lay. Its twin tops_62 reads S on a separate label shot taken four seconds after that garment''s flat-lay. Confirmed with Max as two garments, not one shot twice.'),
('tops_62_peter-millar-red-interclub-polo-s','fit','manual','Size S read at full resolution. See tops_64, which is the same shirt in M.'),
('tops_94_gfore-camiral-camo-polo','notes','manual','Brand read at full resolution as G/FORE after the contact sheet suggested Nike - what looked like a swoosh is a camo shape. Chest reads CAMIRAL.'),
('tops_97_calvin-klein-barnbougle-dunes-polo','condition','manual','Possible small grey marks near the placket, seen in a flat, evenly-lit flat-lay. Recorded as possible, not asserted as damage - nothing was inspected by hand.'),
('tops_98_bcln-white-orange-polo','condition','manual','Possible small marks near the collar, seen in a flat, evenly-lit flat-lay. Recorded as possible, not asserted as damage.')
